import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";var i=JSON.parse(`{"title":"Environment variables","description":"","frontmatter":{},"headers":[],"relativePath":"reference/environment.md","filePath":"reference/environment.md","lastUpdated":1786903141000}`),a={name:`reference/environment.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="environment-variables" tabindex="-1">Environment variables <a class="header-anchor" href="#environment-variables" aria-label="Permalink to “Environment variables”">​</a></h1><table tabindex="0"><thead><tr><th>Variable</th><th>Required</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>OPENGIST_URL</code></td><td>yes</td><td>—</td><td>Root URL of the instance, e.g. <code>https://gist.example.com</code></td></tr><tr><td><code>OPENGIST_TOKEN</code></td><td>yes</td><td>—</td><td>Personal Access Token, starts with <code>og_</code></td></tr><tr><td><code>OPENGIST_READ_ONLY</code></td><td>no</td><td><code>false</code></td><td><code>true</code> registers only the eight read tools</td></tr><tr><td><code>OPENGIST_INSECURE_TLS</code></td><td>no</td><td><code>false</code></td><td><code>true</code> accepts self-signed certificates on the Opengist connection only</td></tr></tbody></table><p>Only the exact string <code>true</code> enables a boolean. <code>1</code>, <code>yes</code> and <code>TRUE</code> are false.</p><h2 id="opengist-url" tabindex="-1"><code>OPENGIST_URL</code> <a class="header-anchor" href="#opengist-url" aria-label="Permalink to “OPENGIST_URL”">​</a></h2><p>The root of the instance, not the API path. A trailing slash is stripped, and a trailing <code>/api</code> is accepted and removed rather than producing <code>/api/api</code>.</p><p>The server exits at startup if the value is not a valid URL, uses a protocol other than <code>http:</code>/<code>https:</code>, or contains a username or password. It warns and continues for plain <code>http://</code> to a non-loopback host — the token and every gist would travel unencrypted.</p><h2 id="opengist-token" tabindex="-1"><code>OPENGIST_TOKEN</code> <a class="header-anchor" href="#opengist-token" aria-label="Permalink to “OPENGIST_TOKEN”">​</a></h2><p>Created in the web UI under <strong>Settings → Access Tokens</strong>. Scopes: <code>gist:read</code>, <code>gist:write</code>, <code>user:read</code>, and <code>user:write</code> for <code>set_gist_like</code>. See <a href="/guide/configuration#required-scopes">Configuration</a> — a token without <code>gist:read</code> does not fail, it silently returns only public gists.</p><p>The value is read once at startup and then removed from <code>process.env</code>, so it is not inherited by child processes and does not appear in <code>/proc/&lt;pid&gt;/environ</code>.</p><p>A token that does not start with <code>og_</code> produces a warning: the usual cause is an account password pasted in its place.</p><h2 id="opengist-read-only" tabindex="-1"><code>OPENGIST_READ_ONLY</code> <a class="header-anchor" href="#opengist-read-only" aria-label="Permalink to “OPENGIST_READ_ONLY”">​</a></h2><p><code>true</code> means <code>create_gist</code>, <code>update_gist</code>, <code>delete_gist_files</code>, <code>delete_gist</code>, <code>fork_gist</code> and <code>set_gist_like</code> are never registered. The model does not see them.</p><p>This is a guard rail in this process, not a boundary — the boundary is the token&#39;s scopes. See <a href="/guide/security#what-actually-holds">Security</a>.</p><h2 id="opengist-insecure-tls" tabindex="-1"><code>OPENGIST_INSECURE_TLS</code> <a class="header-anchor" href="#opengist-insecure-tls" aria-label="Permalink to “OPENGIST_INSECURE_TLS”">​</a></h2><p><code>true</code> disables certificate validation <strong>for connections to <code>OPENGIST_URL</code> only</strong>, through a dedicated undici dispatcher. <code>NODE_TLS_REJECT_UNAUTHORIZED</code> is never set, so no other request the process makes is affected, and the relaxed dispatcher is only selected when the request origin matches the configured instance.</p><p>Prefer installing the CA certificate in the system trust store, or <code>NODE_EXTRA_CA_CERTS</code>, where that is possible.</p><h2 id="starting-without-credentials" tabindex="-1">Starting without credentials <a class="header-anchor" href="#starting-without-credentials" aria-label="Permalink to “Starting without credentials”">​</a></h2><p>If <code>OPENGIST_URL</code> or <code>OPENGIST_TOKEN</code> is missing, the server prints the setup instructions to stderr and <strong>still starts</strong>. It completes the MCP handshake and answers <code>tools/list</code>; every tool call then fails with the same instructions without making a request.</p><p>This is deliberate: registries and sandbox inspectors start the server without secrets, and could not enumerate the tool surface otherwise.</p>`,19)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};